<?php
declare(strict_types=1);
require_once __DIR__ . '/../../includes/functions.php'; require_once __DIR__ . '/../../auth/guard.php'; require_once __DIR__ . '/../../config/database.php'; require_once __DIR__ . '/../../includes/module2_helpers.php'; requireAdmin();
$id=(int)($_GET['id']??0);if($id<=0){setFlash('error','ID không hợp lệ.');redirect('/admin/can-ho/index.php');}$s=$pdo->prepare('SELECT c.*,l.TenLoai FROM CanHo c JOIN LoaiCanHo l ON l.MaLoai=c.MaLoai WHERE c.MaCanHo=:id');$s->execute([':id'=>$id]);$can=$s->fetch();if(!$can){setFlash('error','Không tìm thấy căn hộ.');redirect('/admin/can-ho/index.php');}$s=$pdo->prepare('SELECT * FROM CanHo_Anh WHERE MaCanHo=:id ORDER BY ThuTu,MaAnh');$s->execute([':id'=>$id]);$images=$s->fetchAll();$s=$pdo->prepare('SELECT h.*,k.HoTen TenKhach FROM HopDong h JOIN KhachThue k ON k.MaKhach=h.MaKhach WHERE h.MaCanHo=:id ORDER BY h.NgayBatDau DESC');$s->execute([':id'=>$id]);$contracts=$s->fetchAll();$title='Chi tiết căn '.$can['SoPhong'];require_once __DIR__ . '/../../includes/header.php';
?><div class="page-header"><div><h1>Căn hộ <?=e($can['SoPhong'])?></h1><p class="text-muted">Mã căn #<?=$id?></p></div><div class="actions"><a class="btn btn-secondary" href="edit.php?id=<?=$id?>">Sửa</a><a class="btn btn-light" href="index.php">Danh sách</a></div></div><div class="detail-grid"><section class="detail-card"><h2>Thông tin căn hộ</h2><div class="info-grid"><div><span>Mã căn</span><strong>#<?=$id?></strong></div><div><span>Số phòng</span><strong><?=e($can['SoPhong'])?></strong></div><div><span>Loại</span><strong><?=e($can['TenLoai'])?></strong></div><div><span>Trạng thái</span><?=renderStatusBadge($can['TrangThai'])?></div><div><span>Diện tích</span><strong><?=number_format((float)$can['DienTich'],2,',','.')?> m²</strong></div><div><span>Giá thuê</span><strong><?=formatMoney($can['GiaThue'])?></strong></div></div><div class="description"><span>Mô tả</span><p><?=nl2br(e($can['MoTa']??''))?:'<em>Chưa có mô tả.</em>'?></p></div></section><section class="detail-card"><div class="section-heading"><h2>Album ảnh (<?=count($images)?>)</h2><a href="#upload-image" class="btn btn-primary">Thêm ảnh</a></div><?php if(!$images):?><div class="empty-state">Chưa có ảnh.</div><?php else:?><div class="image-grid" id="apartmentGallery"><?php foreach($images as $index=>$img):$imageUrl=appUrl($img['DuongDan']);?><div class="image-item"><button type="button" class="image-preview-button" data-index="<?=$index?>" data-full="<?=e($imageUrl)?>"><img src="<?=e($imageUrl)?>" alt="Ảnh căn <?=e($can['SoPhong'])?>"></button><?php if((int)$img['LaAnhDaiDien']===1):?><span class="cover-label">Ảnh đại diện</span><?php endif;?><div class="image-actions"><?php if((int)$img['LaAnhDaiDien']!==1):?><form method="post" action="set-anh-dai-dien.php" class="inline-form"><input type="hidden" name="csrf_token" value="<?=e(module2_csrf_token())?>"><input type="hidden" name="id" value="<?=$img['MaAnh']?>"><button class="btn btn-sm btn-secondary">Đặt đại diện</button></form><?php endif;?><form method="post" action="delete-anh.php" class="inline-form"><input type="hidden" name="csrf_token" value="<?=e(module2_csrf_token())?>"><input type="hidden" name="id" value="<?=$img['MaAnh']?>"><button class="btn btn-sm btn-danger">Xóa</button></form></div></div><?php endforeach;?></div><?php endif;?></section><section class="detail-card" id="upload-image"><h2>Thêm ảnh</h2><form method="post" enctype="multipart/form-data" action="upload-anh.php"><input type="hidden" name="csrf_token" value="<?=e(module2_csrf_token())?>"><input type="hidden" name="ma_can_ho" value="<?=$id?>"><input type="file" name="images[]" accept=".jpg,.jpeg,.png,.webp,image/jpeg,image/png,image/webp" multiple required><button class="btn btn-primary">Upload ảnh</button></form></section><section class="detail-card"><h2>Lịch sử hợp đồng</h2><?php if(!$contracts):?><div class="empty-state">Căn hộ chưa có hợp đồng.</div><?php else:?><div class="table-responsive"><table class="data-table"><thead><tr><th>Mã HĐ</th><th>Khách thuê</th><th>Bắt đầu</th><th>Kết thúc</th><th>Giá</th><th>Trạng thái</th></tr></thead><tbody><?php foreach($contracts as $h):?><tr><td>#<?=$h['MaHopDong']?></td><td><?=e($h['TenKhach'])?></td><td><?=formatDate($h['NgayBatDau'])?></td><td><?=formatDate($h['NgayKetThuc'])?></td><td><?=formatMoney($h['GiaThueThoaThuan'])?></td><td><?=renderStatusBadge($h['TrangThai'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section></div><?php require_once __DIR__ . '/../../includes/footer.php'; ?>